import apiClient from './client'
import type { Page, PageParams } from './page'

export type IncidentStatus = 'open' | 'acknowledged' | 'resolved' | 'closed'
export type IncidentSeverity = 'critical' | 'warning' | 'info'

export interface AlertEventRead {
  id: number
  rule_id?: number | null
  node_id?: string | null
  severity: string
  message: string
  labels?: Record<string, unknown> | null
  fired_at?: string | null
}

export interface IncidentAlertRead {
  id: number
  incident_id: number
  alert_event_id: number
  added_at?: string | null
  alert_event?: AlertEventRead | null
}

export interface IncidentRead {
  id: number
  title: string
  description?: string | null
  severity: IncidentSeverity
  status: IncidentStatus
  source: string
  created_by?: number | null
  assigned_to?: number | null
  rule_id?: number | null
  node_id?: string | null
  started_at: string
  acknowledged_at?: string | null
  resolved_at?: string | null
  closed_at?: string | null
  is_deleted: boolean
  created_at: string
  updated_at: string
}

export interface IncidentDetailRead extends IncidentRead {
  alerts: IncidentAlertRead[]
}

export interface IncidentUpdate {
  title?: string
  description?: string
  assigned_to?: number | null
}

export interface IncidentEventRead {
  id: number
  incident_id: number
  event_type: string
  event_subtype?: string | null
  title: string
  description?: string | null
  source?: string | null
  created_by?: number | null
  timestamp: string
  created_at: string
  event_metadata?: Record<string, unknown> | null
}

export interface IncidentNoteCreate {
  content: string
}

export interface IncidentListParams extends PageParams {
  status?: IncidentStatus
  severity?: IncidentSeverity
  node_id?: string
}

export async function getIncidents(params?: IncidentListParams): Promise<Page<IncidentRead>> {
  const response = await apiClient.get<Page<IncidentRead>>('/v1/incidents', { params })
  return response.data
}

export async function getIncident(incidentId: number): Promise<IncidentDetailRead> {
  const response = await apiClient.get<IncidentDetailRead>(`/v1/incidents/${incidentId}`)
  return response.data
}

export async function updateIncident(
  incidentId: number,
  data: IncidentUpdate
): Promise<IncidentRead> {
  const response = await apiClient.put<IncidentRead>(`/v1/incidents/${incidentId}`, data)
  return response.data
}

export async function acknowledgeIncident(incidentId: number): Promise<IncidentRead> {
  const response = await apiClient.post<IncidentRead>(`/v1/incidents/${incidentId}/acknowledge`)
  return response.data
}

export async function resolveIncident(incidentId: number): Promise<IncidentRead> {
  const response = await apiClient.post<IncidentRead>(`/v1/incidents/${incidentId}/resolve`)
  return response.data
}

export async function closeIncident(incidentId: number): Promise<IncidentRead> {
  const response = await apiClient.post<IncidentRead>(`/v1/incidents/${incidentId}/close`)
  return response.data
}

export async function getIncidentTimeline(incidentId: number): Promise<IncidentEventRead[]> {
  const response = await apiClient.get<IncidentEventRead[]>(`/v1/incidents/${incidentId}/timeline`)
  return response.data
}

export async function addIncidentNote(
  incidentId: number,
  data: IncidentNoteCreate
): Promise<IncidentEventRead> {
  const response = await apiClient.post<IncidentEventRead>(
    `/v1/incidents/${incidentId}/timeline/notes`,
    data
  )
  return response.data
}
